$test('hybrid clocks and LWW maps converge without a backend',static function():void{$now=1000;$clockA=new \Pam\Native\Sync\Crdt\HybridLogicalClock('device-a',static fn():int=>$now);$clockB=new \Pam\Native\Sync\Crdt\HybridLogicalClock('device-b',static fn():int=>$now);$a1=$clockA->tick();$a2=$clockA->tick();$b1=$clockB->observe($a2);if($a2->counter!==1||$b1->compare($a2)<=0)throw new RuntimeException('hybrid clock is not monotonic');$left=new \Pam\Native\Sync\Crdt\LastWriteWinsMap();$right=new \Pam\Native\Sync\Crdt\LastWriteWinsMap();$left->assign('title','local',$a1);$right->assign('title','remote',$b1);$right->assign('count',2,$clockB->tick());$left->merge($right);$right->merge($left);if($left->values()!==$right->values()||$left->value('title')!=='remote')throw new RuntimeException('LWW replicas did not converge');$deletedAt=$clockA->observe($clockB->tick());$left->remove('title',$deletedAt);$right->merge($left);$restored=\Pam\Native\Sync\Crdt\LastWriteWinsMap::restore($right->snapshot());if($restored->value('title')!==null||$restored->value('count')!==2)throw new RuntimeException('CRDT snapshot lost a tombstone or value');});
$test('outcome enums are sequential and HTTP transport is server-neutral',static function():void{$values=array_map(static fn($v)=>$v->value,SyncOutcomeStatus::cases());if($values!==[1,2,3,4])throw new RuntimeException('outcome enum mismatch');$fake=NativeTestHarness::install();$response=['outcomes'=>[['id'=>'one','status'=>SyncOutcomeStatus::Applied->value],['id'=>'two','status'=>SyncOutcomeStatus::Conflict->value],['id'=>'three','status'=>SyncOutcomeStatus::Rejected->value,'message'=>'invalid']],'cursor'=>'next','changes'=>[['collection'=>'todos','recordId'=>'one','kind'=>SyncOperationKind::Upsert->value,'payload'=>['title'=>'Server'],'version'=>2,'serverTimestampMillis'=>2000]],'hasMore'=>false];$fake->succeed('http','request',['statusCode'=>200,'body'=>json_encode($response,JSON_THROW_ON_ERROR)]);$fake->succeed('http','request',['statusCode'=>200,'body'=>json_encode($response,JSON_THROW_ON_ERROR)]);$transport=new HttpSyncTransport('https://sync.example.test/v1','device-one',static fn():string=>'token',5000);$push=null;$transport->push([new SyncOperation('one','todos','one',SyncOperationKind::Upsert,['title'=>'Local'],1,1000)],static function($value)use(&$push):void{$push=$value;});if($push?->acknowledged!==['one','two']||$push->conflicts!==1||$push->rejected!==['three'=>'invalid'])throw new RuntimeException('HTTP push mapping failed');$pull=null;$transport->pull('',100,static function($value)use(&$pull):void{$pull=$value;});if($pull?->cursor!=='next'||count($pull->changes)!==1||$pull->changes[0]->payload['title']!=='Server')throw new RuntimeException('HTTP pull mapping failed');$calls=$fake->calls();$payload=Wire::decodeMap($calls[0]->payload);$headers=json_decode((string)$payload['headers'],true,flags:JSON_THROW_ON_ERROR);$body=json_decode((string)$payload['body'],true,flags:JSON_THROW_ON_ERROR);if($payload['url']!=='https://sync.example.test/v1'||$headers['Authorization']!=='Bearer token'||$body['clientId']!=='device-one')throw new RuntimeException('HTTP wire contract mismatch');$fake->assertSatisfied();NativeTestHarness::uninstall();});
$test('SQLite adapter uses native prepared operations',static function():void{$fake=NativeTestHarness::install();$fake->succeed('sqlite','transaction');$fake->succeed('sqlite','execute');$fake->succeed('sqlite','query',['rows'=>json_encode([['id'=>'op1','collection_name'=>'todos','record_id'=>'one','operation_kind'=>1,'payload_json'=>'{"title":"A"}','base_version'=>0,'client_timestamp'=>100,'attempts'=>0]],JSON_THROW_ON_ERROR)]);$store=new SQLiteSyncStore();$store->initialize(static function():void{});$operation=new Pam\Native\Sync\SyncOperation('op1','todos','one',SyncOperationKind::Upsert,['title'=>'A'],0,100);$store->enqueue($operation,static function():void{});$pending=[];$store->pending(10,static function($value)use(&$pending):void{$pending=$value;});if(count($pending)!==1||$pending[0]->payload['title']!=='A')throw new RuntimeException('SQLite mapping failed');$fake->assertSatisfied();NativeTestHarness::uninstall();});
$test('fails safely when the pull page budget is exhausted',static function():void{$store=new InMemorySyncStore();$transport=new class implements SyncTransport{public int$pulls=0;public function push(array$o,Closure$c):void{$c(new SyncPushResult([]));}public function pull(string$cursor,int$limit,Closure$c):void{$this->pulls++;$c(new SyncPullResult('cursor-'.$this->pulls,[],true));}};$engine=new SyncEngine($store,$transport,maxPullPages:2);$report=null;$engine->synchronize(static function($value)use(&$report):void{$report=$value;});if($transport->pulls!==2||$report?->state!==SyncRunState::Failed||!str_contains((string)$report->message,'resume from the committed cursor'))throw new RuntimeException(sprintf('pull page budget was not enforced (pulls=%d state=%s message=%s)',$transport->pulls,$report?->state->name??'null',$report?->message??'null'));});
